code_examples.text:
when ... {
    NAME::lookup $myHostname
}
when NAME_RESOLVED {
    log local0. "NAME_RESOLVED: [NAME::response]"
    set server_ip [NAME::response address 0]
}

when CLIENT_ACCEPTED {
    NAME::lookup [IP::client_addr]
}
when NAME_RESOLVED {
    log local0. "Client IP resolves to [NAME::response name]"
}
